SELECT DISTINCTROW [2febbraiogen].Difetto, Sum([2febbraiogen].ConteggiodiCommessa) AS SommadiConteggiodiCommessa, [2febbraio300].Difetto, Sum([2febbraio300].ConteggiodiCommessa) AS SommadiConteggiodiCommessa1, [2febbraio1000].Difetto, Sum([2febbraio1000].ConteggiodiCommessa) AS SommadiConteggiodiCommessa3, [2febbraio+1000].Difetto, Sum([2febbraio+1000].ConteggiodiCommessa) AS SommadiConteggiodiCommessa2 INTO QualitaFebbraio
FROM ((2febbraiogen LEFT JOIN 2febbraio300 ON [2febbraiogen].Difetto = [2febbraio300].Difetto) LEFT JOIN 2febbraio1000 ON [2febbraiogen].Difetto = [2febbraio1000].Difetto) LEFT JOIN [2febbraio+1000] ON [2febbraiogen].Difetto = [2febbraio+1000].Difetto
GROUP BY [2febbraiogen].Difetto, [2febbraio300].Difetto, [2febbraio1000].Difetto, [2febbraio+1000].Difetto;
